const raw = $json.output;

let parsed;

try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  const match = String(raw || '').match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : {};
}

let result = parsed.output || parsed.response || parsed;

if (typeof result === 'string') {
  try {
    result = JSON.parse(result);
  } catch (error) {
    const match = String(result || '').match(/\{[\s\S]*\}/);
    result = match ? JSON.parse(match[0]) : {};
  }
}

result = result || {};

function isTrue(value) {
  return value === true || String(value || '').toLowerCase() === 'true';
}

function normalizeEscalationType(value) {
  return String(value || '').trim().toUpperCase();
}

function normalizePlaybookCitation(value, result) {
  const text = String(value || '').toLowerCase();
  const classification = String(result.classification || '').toUpperCase();
  const resolution = String(result.resolution || '').toUpperCase();
  const rationale = String(result.rationale || '').toLowerCase();
  const escalationType = normalizeEscalationType(result.escalation_type);
  const escalationRequired = isTrue(result.escalation_required);

  const citations = [];

  function addCitation(label) {
    if (label && !citations.includes(label)) {
      citations.push(label);
    }
  }

  // Preserve any approved labels already returned by the Resolution Agent.
  if (text.includes('routine event')) {
    addCitation('Playbook: Routine Event');
  }

  if (text.includes('address issue')) {
    addCitation('Playbook: Address Issue');
  }

  if (text.includes('failed delivery attempts') || text.includes('failed delivery') || text.includes('third failed') || text.includes('attempt')) {
    addCitation('Playbook: Failed Delivery Attempts');
  }

  if (text.includes('locker reroute') || text.includes('locker')) {
    addCitation('Playbook: Locker Reroute');
  }

  if (text.includes('damaged perishable')) {
    addCitation('Playbook: Damaged Perishable');
  }

  if (text.includes('damaged package')) {
    addCitation('Playbook: Damaged Package');
  }

  if (text.includes('refused delivery') || text.includes('refused') || text.includes('return')) {
    addCitation('Playbook: Refused Delivery');
  }

  if (text.includes('weather delays') || text.includes('weather')) {
    addCitation('Playbook: Weather Delays');
  }

  if (text.includes('escalation matrix') || text.includes('escalation')) {
    addCitation('Playbook: Escalation Matrix');
  }

  // Infer citations from structured output when the citation text is incomplete.
  if (classification === 'ROUTINE' || resolution === 'N/A') {
    addCitation('Playbook: Routine Event');
  }

  if (classification === 'ADDRESS_ISSUE') {
    addCitation('Playbook: Address Issue');
  }

  if (classification === 'ATTEMPTED' || rationale.includes('failed attempt') || rationale.includes('delivery attempt')) {
    addCitation('Playbook: Failed Delivery Attempts');
  }

  if (classification === 'REROUTE_TO_LOCKER' || resolution === 'REROUTE_TO_LOCKER' || rationale.includes('locker')) {
    addCitation('Playbook: Locker Reroute');
  }

  if (classification === 'DAMAGED' && (rationale.includes('perishable') || text.includes('perishable'))) {
    addCitation('Playbook: Damaged Perishable');
  } else if (classification === 'DAMAGED') {
    addCitation('Playbook: Damaged Package');
  }

  if (classification === 'REFUSED' || resolution === 'RETURN_TO_SENDER') {
    addCitation('Playbook: Refused Delivery');
  }

  if (classification === 'WEATHER_DELAY') {
    addCitation('Playbook: Weather Delays');
  }

  // Generic escalation citation rule.
  // This is intentionally policy-based, not shipment-specific.
  if (
    escalationRequired ||
    escalationType === 'AUTOMATIC' ||
    escalationType === 'DISCRETIONARY'
  ) {
    addCitation('Playbook: Escalation Matrix');
  }

  // Fallback if no citation could be inferred.
  if (citations.length === 0) {
    addCitation(value || 'Playbook: Routine Event');
  }

  // Preferred ordering for cleaner observability.
  const preferredOrder = [
    'Playbook: Routine Event',
    'Playbook: Address Issue',
    'Playbook: Failed Delivery Attempts',
    'Playbook: Locker Reroute',
    'Playbook: Damaged Package',
    'Playbook: Damaged Perishable',
    'Playbook: Refused Delivery',
    'Playbook: Weather Delays',
    'Playbook: Escalation Matrix'
  ];

  return preferredOrder
    .filter(label => citations.includes(label))
    .join(', ');
}

result.playbook_citation = normalizePlaybookCitation(result.playbook_citation, result);

let seededTools = [];
try {
  seededTools = $('Evaluate Escalation Rules').first().json.tools_used_seed || [];
} catch (error) {
  seededTools = [];
}

const toolsUsed = Array.from(new Set([
  ...(Array.isArray(result.tools_used) ? result.tools_used : []),
  ...seededTools
]));

result.tools_used = toolsUsed;

return [
  {
    json: {
      ...$json,
      resolution_result: result,
      is_exception: result.is_exception,
      classification: result.classification,
      resolution: result.resolution,
      escalation_required: result.escalation_required,
      escalation_type: result.escalation_type,
      recommended_next_step: result.recommended_next_step,
      rationale: result.rationale,
      playbook_citation: result.playbook_citation,
      tools_used: result.tools_used
    }
  }
];

const raw = $json.output;

let parsed;

try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  const text = String(raw || '').trim();
  parsed = { decision: text };
}

const result = parsed.output || parsed.response || parsed;

const decisionText = String(
  result.decision ||
  result.status ||
  result.verdict ||
  result.output ||
  raw ||
  ''
).trim();

const decisionUpper = decisionText.toUpperCase();
const firstLine = decisionUpper.split(/\r?\n/)[0].trim();

const needsRevision =
  result.needs_revision === true ||
  result.needs_revision === 'true' ||
  firstLine === 'REVISE' ||
  firstLine === 'REVISION_REQUIRED' ||
  firstLine === 'REJECT' ||
  decisionUpper.startsWith('REVISE') ||
  decisionUpper.includes('NEEDS REVISION') ||
  decisionUpper.includes('REVISION REQUIRED');

const escalatedByCritic =
  result.escalate === true ||
  result.escalate === 'true' ||
  firstLine === 'ESCALATE' ||
  decisionUpper.startsWith('ESCALATE');

const approved =
  !needsRevision &&
  !escalatedByCritic &&
  (
    result.approved === true ||
    result.approved === 'true' ||
    firstLine === 'ACCEPT' ||
    firstLine === 'APPROVED' ||
    firstLine === 'APPROVE' ||
    decisionUpper.startsWith('ACCEPT') ||
    decisionUpper.includes('ACCEPT THE RESOLUTION OUTPUT') ||
    decisionUpper.includes('I WILL ACCEPT') ||
    decisionUpper.includes('I WILL ACCEPT THE RESOLUTION OUTPUT') ||
    decisionUpper.endsWith('ACCEPT')
  );

const normalizedDecision = escalatedByCritic
  ? 'ESCALATE'
  : needsRevision
    ? 'REVISE'
    : approved
      ? 'ACCEPT'
      : 'UNKNOWN';

const feedback =
  result.feedback ||
  result.rationale ||
  result.reason ||
  decisionText.replace(/^(ACCEPT|REVISE|ESCALATE)\s*[:\-\n]?\s*/i, '').trim();

return [
  {
    json: {
      ...$json,
      critic_result: result,
      critic_decision: normalizedDecision,
      critic_approved: approved,
      needs_revision: needsRevision,
      critic_escalate: escalatedByCritic,
      critic_feedback: feedback,
      critic_issues: result.issues || [],
      critic_confidence: result.confidence || null
    }
  }
];

const raw = $json.output;

function tryParseJson(value) {
  if (value === null || value === undefined) return {};

  if (typeof value !== 'string') return value;

  const text = value.trim();

  try {
    return JSON.parse(text);
  } catch (error) {
    const match = text.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        return JSON.parse(match[0]);
      } catch (innerError) {}
    }
  }

  return { decision: text };
}

function unwrapParsed(value) {
  const parsed = tryParseJson(value);

  if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
    return parsed.output || parsed.response || parsed;
  }

  return parsed;
}

function getCommunicationOutputRaw() {
  try {
    return $('Communication Agent').first().json.output;
  } catch (error) {
    return null;
  }
}

function getResolutionDecided() {
  try {
    return $('Resolution Decided').first().json;
  } catch (error) {
    return {};
  }
}

function parseCommunicationOutput(value) {
  const parsed = unwrapParsed(value);

  if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
    const nested = parsed.output || parsed.response;

    if (typeof nested === 'string') {
      return parseCommunicationOutput(nested);
    }

    return {
      channel: parsed.channel || parsed.communication_channel || '',
      message: parsed.message || parsed.customer_message || parsed.text || ''
    };
  }

  return {
    channel: '',
    message: String(value || '').trim()
  };
}

const parsed = tryParseJson(raw);
const result = parsed.output || parsed.response || parsed;

const decisionText = String(
  result.decision ||
  result.status ||
  result.verdict ||
  result.output ||
  raw ||
  ''
).trim();

const decisionUpper = decisionText.toUpperCase();
const firstLine = decisionUpper.split(/\r?\n/)[0].trim();

const needsRevision =
  result.needs_revision === true ||
  result.needs_revision === 'true' ||
  firstLine === 'REVISE' ||
  firstLine === 'REVISION_REQUIRED' ||
  firstLine === 'REJECT' ||
  decisionUpper.includes('NEEDS REVISION') ||
  decisionUpper.includes('REVISION REQUIRED') ||
  decisionUpper.startsWith('REVISE');

const escalatedByCritic =
  result.escalate === true ||
  result.escalate === 'true' ||
  firstLine === 'ESCALATE' ||
  decisionUpper.startsWith('ESCALATE');

const approved =
  !needsRevision &&
  !escalatedByCritic &&
  (
    result.approved === true ||
    result.approved === 'true' ||
    firstLine === 'ACCEPT' ||
    firstLine === 'APPROVED' ||
    firstLine === 'APPROVE' ||
    decisionUpper.startsWith('ACCEPT') ||
    decisionUpper.includes('ACCEPT THE MESSAGE') ||
    decisionUpper.includes('ACCEPT THE COMMUNICATION') ||
    decisionUpper.endsWith('ACCEPT')
  );

const normalizedDecision = escalatedByCritic
  ? 'ESCALATE'
  : needsRevision
    ? 'REVISE'
    : approved
      ? 'ACCEPT'
      : 'UNKNOWN';

const feedback =
  result.feedback ||
  result.rationale ||
  result.reason ||
  decisionText.replace(/^(ACCEPT|REVISE|ESCALATE)\s*[:\-]?\s*/i, '').trim();

const communicationOutputRaw = getCommunicationOutputRaw();
const communicationOutput = parseCommunicationOutput(communicationOutputRaw);
const resolutionDecided = getResolutionDecided();

return [
  {
    json: {
      ...$json,
      communication_output_raw: communicationOutputRaw,
      communication_output: communicationOutput,
      communication_channel: communicationOutput.channel,
      customer_message: communicationOutput.message,
      resolution_decided: resolutionDecided,
      communication_critic_result: result,
      communication_critic_decision: normalizedDecision,
      communication_critic_approved: approved,
      communication_needs_revision: needsRevision,
      communication_escalate: escalatedByCritic,
      communication_critic_feedback: feedback,
      communication_critic_issues: result.issues || [],
      communication_critic_confidence: result.confidence || null
    }
  }
];

return $input.all().map(item => {
  const rationale = String(item.json.rationale || '').toLowerCase();
  const statusCode = String(
    item.json.consolidated_event?.status_code ||
    item.json.status_code ||
    ''
  ).toUpperCase();

  const routineStatuses = ['SCANNED', 'DELIVERED', 'IN_TRANSIT', 'OUT_FOR_DELIVERY'];

  const isRoutineGuardrail =
    String(item.json.is_exception || '').toUpperCase() === 'NO' &&
    (
      rationale.includes('routine operational noise') ||
      routineStatuses.includes(statusCode)
    );

  if (isRoutineGuardrail) {
    item.json.playbook_citations = ['Playbook: Routine Event'];
  } else if (!Array.isArray(item.json.playbook_citations)) {
    item.json.playbook_citations = [];
  }

  return item;
});

return $input.all().map(item => {
  const j = item.json || {};

  return {
    json: {
      shipment_id: j.shipment_id,
      is_exception: j.is_exception,
      resolution: j.resolution,
      escalated: j.escalated,
      tone_label: j.tone_label || "N/A",
      channel: j.channel || "N/A",
      customer_message: j.customer_message || "",
      rationale: j.rationale || "",
      tools_used: Array.isArray(j.tools_used) ? j.tools_used : [],
      playbook_citations: Array.isArray(j.playbook_citations) ? j.playbook_citations : []
    }
  };
});
